3	/**
4	 * The embedded Payment step — replaces the old "order summary + Deploy button
5	 * that pops a Stripe-hosted modal" Review UI with a real, on-page payment form:
6	 * a radio-selectable list of payment methods (Card inline, Google Pay / Apple
7	 * Pay / PayPal / Coinbase Commerce as their own rows) on the left, and a live
8	 * order summary + security/trust cards on the right.
9	 *
10	 * ARCHITECTURE (see lib/stripe.ts's block comment above
11	 * `createOrderPaymentSession` for the full reasoning):
12	 *
13	 *   - Card / Google Pay / Apple Pay all run through ONE Stripe Custom Checkout
14	 *     session (`ui_mode: "elements"`), mounted here via `stripe.initCheckout()`
15	 *     (the `@stripe/react-stripe-js/checkout` `CheckoutElementsProvider` + `PaymentElement` +
16	 *     `ExpressCheckoutElement`). Raw card data never reaches our server — the
17	 *     Payment Element's iframe owns those fields, exactly as Embedded Checkout's
18	 *     did. The session is a normal Checkout Session, so Stripe's existing
19	 *     webhook + `classifyCheckoutSession` + `fulfilCheckoutSession` pipeline
20	 *     fulfils it completely unchanged.
21	 *   - PayPal is a genuine second rail (lib/paypal.ts, real Orders API) —
22	 *     `@paypal/react-paypal-js`'s `<PayPalButtons>` creates a PayPal order via
23	 *     our own server action, then captures it server-to-server on approval.
24	 *   - Coinbase Commerce is a genuine third rail — clicking it creates a charge
25	 *     server-side and redirects to Coinbase's own hosted charge page (there is
26	 *     no embeddable Coinbase Commerce widget), returning here once paid.
27	 *   - PayPal and Coinbase both funnel into `fulfilExternalPayment`
28	 *     (lib/fulfil-checkout.ts), the SAME dispatch Stripe's webhook uses.
29	 *
30	 * This component is presentational + payment-orchestration only: pricing,
31	 * promo/coupon holds and provisioning all happen server-side, exactly as they
32	 * did before this UI existed. Every number shown here is a PROP, never computed
33	 * in this file, so the wizard's existing pricing math remains the single source
34	 * of truth (see each wizard's own dueCents/cardCents/walletApplied derivation).
35	 */
36	
37	import { useEffect, useMemo, useState } from "react";
38	import { loadStripe, type Stripe as StripeJs } from "@stripe/stripe-js";
39	// Custom Checkout's React bindings all moved to this subpath in v6 —
40	// CheckoutProvider was renamed CheckoutElementsProvider, and PaymentElement/
41	// ExpressCheckoutElement here are DIFFERENT component instances from the
42	// main package's (context-scoped to CheckoutElementsProvider, not <Elements>)
43	// — importing them from "@stripe/react-stripe-js" instead throws "Could not
44	// find Elements context" at runtime even though both packages export a
45	// same-named component. useCheckout() itself is unchanged/back-compat, but
46	// deprecated since v6.3 in favor of the provider-specific useCheckoutElements().
47	import {
48	  CheckoutElementsProvider,
49	  useCheckoutElements,
50	  PaymentElement,
51	  ExpressCheckoutElement,
52	} from "@stripe/react-stripe-js/checkout";
53	import { PayPalScriptProvider, PayPalButtons, FUNDING } from "@paypal/react-paypal-js";
54	import { PaymentTrustBar } from "@/components/customer/PaymentTrustBar";
55	
56	export type PaymentStepOrderLine = {
57	  icon: React.ReactNode;
58	  name: string;
59	  /** e.g. "4 vCPU · 8 GB RAM · 160 GB NVMe · 12 months" */
60	  specLines: string[];
61	  /** The line item's own price label, e.g. "$71.88" or "$5.99/mo". */
62	  priceLabel: string;
63	};
64	
65	export type PaymentStepSummary = {
66	  lines: PaymentStepOrderLine[];
67	  /** Plan / Install / Add-ons / Hostname / etc — the config details that used
68	   *  to live in a separate "Review & deploy" list above this card, duplicating
69	   *  it. Rendered as plain key-value rows between the line items and the
70	   *  pricing breakdown, so there is exactly ONE place on the page showing
71	   *  what's being bought. */
72	  details?: { k: string; v: React.ReactNode }[];
73	  billingTermLabel: string;
74	  /** The term's discount rate (%), shown next to `billingTermLabel` — e.g.
75	   *  "Annual · Save 20%". Omitted (or 0) shows no badge, matching a Monthly
76	   *  term which has nothing to discount. */
77	  discountPercent?: number;
78	  /** Compact billing-term summary, shown instead of a second full term
79	   *  picker — the Plan step already has one. `onChangeTerm` toggles an
80	   *  inline reveal of that same picker (wired up by the wizard), rather than
81	   *  navigating away from the last step of the checkout. */
82	  onChangeTerm?: () => void;
83	  /** First-month-free (or similar) renewal disclosure — "you pay X today,
84	   *  then Y when it renews" — injected as a slot since the wording and the
85	   *  numbers behind it are wizard/product-specific. */
86	  promoExplainer?: React.ReactNode;
87	  setupFeeCents?: number;
88	  /** What the wallet balance covers, if anything (shown as a credit line). */
89	  walletAppliedCents?: number;
90	  taxCents?: number;
91	  taxLabel?: string;
92	  /** What is actually charged to the chosen payment method today. */
93	  totalDueCents: number;
94	  onEdit: () => void;
95	  /** The promo-code input + apply/remove controls — wizard-specific state
96	   *  (couponInput/couponBusy/couponApplied all live in the wizard, not here),
97	   *  injected as a slot so this component stays generic across products. */
98	  promoCodeSlot?: React.ReactNode;
99	  /** The "Apply my wallet balance" checkbox — same reasoning as promoCodeSlot. */
100	  walletToggleSlot?: React.ReactNode;
101	};
