103	type StripeSessionState =
104	  | { status: "idle" }
105	  | { status: "loading" }
106	  | { status: "ready"; clientSecret: string; publishableKey: string }
107	  | { status: "error"; message: string };
108	
109	export type PaymentStepProps = {
110	  summary: PaymentStepSummary;
111	  email: string;
112	  onBack: () => void;
113	
114	  /** Stripe: card / Google Pay / Apple Pay. */
115	  stripe: StripeSessionState;
116	  /** Ask the parent to (re)create the Stripe Custom Checkout session. Called
117	   *  automatically on mount/price-change AND from the "try again" control. */
118	  onRequestStripeSession: () => void;
119	
120	  /** PayPal — omitted from the method list entirely when not configured. */
121	  paypal: { ready: boolean; clientId: string } | null;
122	  createPayPalOrder: () => Promise<{ paypalOrderId: string; pendingId: string } | { error: string }>;
123	  capturePayPalOrder: (paypalOrderId: string, pendingId: string) => Promise<{ redirect?: string; error?: string }>;
124	
125	  /** Coinbase Commerce — omitted entirely when not configured. */
126	  coinbaseReady: boolean;
127	  createCoinbaseCharge: () => Promise<{ hostedUrl: string; pendingId: string } | { error: string }>;
128	
129	  /** Only populate when a product has a REAL, published, honoured guarantee.
130	   *  See WizardTrustBar.tsx / PaymentTrustBar.tsx's HONESTY notes — there is
131	   *  none today, so every current caller omits this and the callout is hidden
132	   *  rather than showing a fabricated claim. */
133	  moneyBackDays?: number;
134	
135	  /** Explains why "Save card" is checked and disabled. Defaults to the
136	   *  auto-renewing-subscription copy, which is only true for products this
137	   *  platform actually auto-charges a saved card for at renewal (VPS,
138	   *  hosting, game servers, email). Domain registration is NOT one of those
139	   *  — renewals only ever draw from the wallet (worker/billing.ts's
140	   *  domainAutoRenewSweep has no card-fallback branch, unlike server
141	   *  renewals) — so DomainRegisterWizard.tsx overrides this with accurate
142	   *  copy rather than repeating a claim that isn't true for that product. */
143	  saveCardExplainer?: React.ReactNode;
144	};
