223	function MethodRow({
224	  id, selected, onSelect, icon, title, subtitle, badge, children, disabled, alwaysOpen,
225	}: {
226	  id: Method;
227	  selected: boolean;
228	  onSelect: () => void;
229	  icon: React.ReactNode;
230	  title: string;
231	  subtitle: string;
232	  badge?: { text: string; cls: string };
233	  children?: React.ReactNode;
234	  disabled?: boolean;
235	  /** Render `children` even when this row isn't the selected method. Used by
236	   *  Google Pay / Apple Pay: their real button (an `ExpressCheckoutElement`,
237	   *  not a placeholder) is the whole point of a one-click wallet — hiding it
238	   *  behind "select this row, then click again" defeats that, and looked
239	   *  like a static, non-interactive row rather than a real Stripe control. */
240	  alwaysOpen?: boolean;
241	}) {
