271	/* ------------------------------------------------------------------ *
272	 * Card + Google Pay + Apple Pay — all children of ONE CheckoutElementsProvider
273	 * ------------------------------------------------------------------ */
274	
275	const stripeCache = new Map<string, Promise<StripeJs | null>>();
276	/** Exported so components/customer/AddFundsPaymentModal.tsx shares the SAME
277	 *  cached Stripe.js instance/appearance rather than re-deriving them — the
278	 *  wallet top-up's Custom Checkout must look and behave identically to this
279	 *  Payment step, not merely similarly. */
280	export function stripeFor(pk: string): Promise<StripeJs | null> {
281	  let p = stripeCache.get(pk);
282	  if (!p) {
283	    p = loadStripe(pk);
284	    stripeCache.set(pk, p);
285	  }
286	  return p;
287	}
288	
289	/**
290	 * Shared appearance so the Payment Element reads as part of THIS page, not a
291	 * visiting Stripe widget — dark surfaces matching the wizard's card chrome.
292	 *
293	 * `fontFamily: "inherit"` looked like it would pick up the page's own Geist
294	 * typeface, but Elements render inside a cross-origin js.stripe.com iframe —
295	 * "inherit" resolves against THAT document, which has no ancestor font-family
296	 * of its own, so it fell through to the browser default serif (a real bug: it
297	 * rendered as a dated Times New Roman look, not Geist). `STRIPE_FONTS` loads
298	 * the actual typeface into the iframe via Stripe's documented `cssSrc` option
299	 * (the one way to add a custom font — same-origin @font-face rules on the
300	 * parent page are invisible to the iframe), and `fontFamily` below names it.
301	 */
302	export const STRIPE_FONTS = [{ cssSrc: "https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&display=swap" }];
303	export const STRIPE_APPEARANCE = {
304	  theme: "night" as const,
305	  variables: {
306	    colorPrimary: "#7c5cff",
307	    colorBackground: "#0b0f1f",
308	    colorText: "#e2e8f0",
309	    colorDanger: "#f87171",
310	    fontFamily: "'Geist', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif",
311	    borderRadius: "10px",
312	    spacingUnit: "4px",
313	  },
314	  rules: {
315	    ".Input": { border: "1px solid rgba(255,255,255,0.09)", boxShadow: "none" },
316	    ".Input:focus": { border: "1px solid rgba(124,92,255,0.6)", boxShadow: "0 0 0 1px rgba(124,92,255,0.4)" },
317	    ".Label": { color: "#94a3b8" },
318	  },
319	};
320	
321	/** Renders inside `<CheckoutElementsProvider>` — the only place `useCheckout()` is valid. */
322	function CardAndWalletsBlock({
323	  selected,
324	  onSelectCard,
325	  saveCard,
326	  onToggleSaveCard,
327	  totalDueCents,
328	  saveCardExplainer,
329	}: {
330	  selected: Method;
331	  onSelectCard: () => void;
332	  saveCard: boolean;
333	  onToggleSaveCard: (v: boolean) => void;
334	  totalDueCents: number;
335	  saveCardExplainer: React.ReactNode;
336	}) {
337	  // useCheckoutElements() (not the deprecated useCheckout()) returns a
338	  // discriminated union — {type:"loading"} while the Elements SDK is still
339	  // initializing, {type:"error"} if it failed, {type:"success", checkout}
340	  // once ready. `checkoutActions` is that inner `checkout` object, undefined
341	  // until "success" — every confirm() call below is guarded on it existing,
342	  // so a click during the loading window can't throw.
343	  const checkoutState = useCheckoutElements();
344	  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
345	  const [confirming, setConfirming] = useState(false);
346	  const [error, setError] = useState<string | null>(null);
347	  const [name, setName] = useState("");
348	  const [expressPayAvailable, setExpressPayAvailable] = useState(false);
349	
350	  async function payWithCard() {
351	    if (!checkoutActions) return;
352	    setError(null);
353	    setConfirming(true);
354	    try {
355	      const result = await checkoutActions.confirm({ savePaymentMethod: saveCard });
356	      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another payment method.");
357	      // On success Stripe navigates the browser to the session's return_url
358	      // (/api/stripe/confirm) — the SAME route that fulfils every other Stripe
359	      // payment on this platform. Nothing else to do here.
360	    } catch {
361	      setError("Something went wrong confirming your payment. Please try again.");
362	    } finally {
363	      setConfirming(false);
364	    }
365	  }
366	
367	  return (
368	    <>
369	      <MethodRow
370	        id="card"
371	        selected={selected === "card"}
372	        onSelect={onSelectCard}
373	        icon={<CardIcon />}
374	        title="Credit / Debit Card"
375	        subtitle="Visa, Mastercard, American Express and more"
376	      >
377	        <div className="space-y-4">
378	          <div>
379	            <label className="mb-1.5 flex items-center gap-1.5 text-xs font-medium text-slate-400">
380	              <LockIcon /> Card details
381	            </label>
382	            <div className="rounded-lg border border-white/[0.08] bg-white/[0.02] p-3">
383	              <PaymentElement
384	                options={{
385	                  layout: "tabs",
386	                  fields: { billingDetails: { name: "never" } },
387	                  paymentMethodOrder: ["card"],
388	                }}
389	              />
390	            </div>
391	          </div>
392	          <div>
393	            <label className="mb-1.5 block text-xs font-medium text-slate-400">Cardholder name</label>
394	            <input
395	              type="text"
396	              value={name}
397	              onChange={(e) => setName(e.target.value)}
398	              placeholder="Name on card"
399	              className="w-full rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:border-brand-400/50 focus:outline-none"
400	            />
401	          </div>
402	          <label className="flex items-start gap-2.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
403	            <input type="checkbox" checked={saveCard} disabled className="mt-0.5 h-3.5 w-3.5 accent-brand-500" onChange={(e) => onToggleSaveCard(e.target.checked)} />
404	            <span className="text-xs text-slate-400">
405	              <span className="font-medium text-slate-300">Save card for faster checkout</span>
406	              <br />
407	              {saveCardExplainer}
408	            </span>
409	          </label>
410	          {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}
411	          <button
412	            type="button"
413	            onClick={payWithCard}
414	            disabled={confirming || !checkoutActions?.canConfirm}
415	            className="btn-deploy w-full py-3 text-sm"
416	          >
417	            <LockIcon className="h-4 w-4" />
418	            {confirming ? "Processing…" : `Pay Securely ${money(totalDueCents)}`}
419	            {!confirming && <span className="dep-arrow">→</span>}
420	          </button>
421	        </div>
422	      </MethodRow>
423	
424	      {/*
425	        ONE ExpressCheckoutElement, always mounted, showing whichever wallets
426	        the browser/device actually supports (Stripe renders them side by
427	        side itself). This used to be TWO separate elements — one per wallet,
428	        each shown only when its own MethodRow was the "selected" radio
429	        option — which looked static (nothing to click until you clicked the
430	        row first) and, worse, having both mount at once (needed to fix the
431	        static look) throws Stripe's own "cannot create multiple instances of
432	        the Express Checkout Element" error. A single instance covering both
433	        wallets is Stripe's actual supported shape for this. Hidden entirely
434	        (via onReady's availablePaymentMethods) when NEITHER wallet is
435	        available on this browser/device/card.
436	      */}
437	      {/* Always mounted (never conditionally unmounted) so onReady gets a
438	          chance to fire at all — only its VISIBILITY is gated on the result,
439	          via a CSS class rather than removing it from the tree. */}
440	      <div className={expressPayAvailable ? "rounded-xl border border-white/[0.07] bg-white/[0.02] p-4" : "hidden"}>
441	          <p className="mb-3 text-xs font-medium text-slate-400">Express checkout</p>
442	          <ExpressCheckoutElement
443	            options={{
444	              // The /checkout subpath's ExpressCheckoutElementOptions requires
445	              // every key present (unlike the main package's), even though
